contracts/FilmmakerCampaign.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./MovieTicket.sol";

/**
 * @title FilmmakerCampaign
 * @dev Decentralflix Crowdfunding + Milestone Escrow + InvestmentNFTs — UTILITY ONLY (HIGHEST LEGAL RISK AREA)
 *
 * CRITICAL LEGAL WARNING (Step 3 — user-provided research):
 * Producer-tier crowdfunding + milestone escrow + AI review windows create the highest exposure under Howey test.
 * - All InvestmentNFTs and backings are STRICTLY UTILITY/ACCESS tokens only.
 * - NO promises of returns, repayment, profits, or completion.
 * - Platform provides ZERO custody; funds live only in this contract's escrow.
 * - Milestone proofs submitted by Producer-tier backers have a mandatory 48-72h review window (non-custodial design).
 *
 * This contract must be read together with:
 * - docs/legal/ToS.md §4 (NFTs, Crowdfunding, Escrow)
 * - docs/legal/RESEARCH_AND_INTEGRATION.md (Howey + money transmission analysis)
 * - Clickwrap consent modal enforced in frontend before any launch/contribute/AI-proof action.
 *
 * Section 230 / DMCA: Platform-level protection for UGC. Contract itself only handles value escrow and access claims.
 * All legal documents and contract comments require review by licensed counsel before mainnet deployment.
 *
 * Allows filmmakers to launch NFT-backed crowdfunding campaigns.
 * Backers receive InvestmentNFTs (permanent access claim + investment proof).
 * Funds held in escrow, released only on owner-approved milestones.
 * Special 48-72h admin review window for milestone proof submissions from Producer-tier backers.
 *
 * Reuses Tier enum, patterns, and philosophy from MovieTicket + SeederCredits.
 * Arweave-first for all rich metadata/proofs (immutable, censorship-resistant).
 * Owner (platform dev) has moderation power for AI reviews + emergency controls.
 */
contract FilmmakerCampaign is ERC721, ERC721URIStorage, Ownable, ReentrancyGuard {
    MovieTicket public immutable movieTicket;

    enum CampaignStatus { ACTIVE, FUNDED, FAILED, DELIVERED }

    struct TierConfig {
        uint256 price;
        uint256 maxSupply;
        uint256 sold;
    }

    struct Milestone {
        string desc;
        uint256 amount;
        bool approved;
        uint256 approvedAt;
        bool isAI;
        string proofHash;          // Arweave
        uint256 aiReviewDeadline;  // 0 if not AI
    }

    struct Campaign {
        address filmmaker;
        string metadataHash;       // Arweave JSON (pitch, title, poster, milestones, etc.)
        uint256 target;
        uint256 raised;
        uint256 deadline;
        CampaignStatus status;
        TierConfig[3] tiers;       // 0=BASIC, 1=DELUXE, 2=PRODUCER
        Milestone[] milestones;
    }

    uint256 public nextCampaignId;
    uint256 public aiReviewWindow = 72 hours;

    mapping(uint256 => Campaign) public campaigns;
    mapping(uint256 => uint256) public campaignEscrow;
    mapping(uint256 => mapping(address => uint256)) public backerTotals; // campaignId => backer => total invested

    // InvestmentNFTs (campaign-scoped for simplicity)
    mapping(uint256 => uint256) public tokenCampaign; // tokenId => campaignId
    mapping(uint256 => MovieTicket.Tier) public tokenTiers;

    // Phase 0: track minted tokenIds for reliable/accurate enumeration (improves prior loose 0..totalSupply scan over sparse IDs)
    uint256[] private _mintedTokens;

    // Simple mapping for campaign -> videoHash association. Enables clean hasCrowdfundAccess without relying on off-chain Arweave metadata parsing.
    // Set by filmmaker or owner (e.g. on delivery or launch). Phase 0 practicality for video gating of backers.
    mapping(uint256 => string) public campaignVideoHash;

    event CampaignLaunched(uint256 indexed id, address filmmaker, string metadataHash, uint256 target);
    event Contribution(uint256 indexed campaignId, address indexed backer, MovieTicket.Tier tier, uint256 amount, uint256 tokenId);
    event MilestoneSubmitted(uint256 indexed campaignId, uint256 mId, string proofHash, bool isAI);
    event AIReviewed(uint256 indexed campaignId, uint256 mId, bool approved);
    event MilestoneReleased(uint256 indexed campaignId, uint256 mId, uint256 amount, address filmmaker);
    event RefundClaimed(uint256 indexed campaignId, address indexed backer, uint256 amount);
    event AIReviewWindowUpdated(uint256 newWindow);
    event CampaignVideoLinked(uint256 indexed campaignId, string videoHash);

    constructor(address _movieTicket) Ownable(msg.sender) ERC721("Decentralflix Crowdfund Pass", "DFCP") {
        require(_movieTicket != address(0), "Invalid MovieTicket");
        movieTicket = MovieTicket(_movieTicket);
    }

    function setAIReviewWindow(uint256 _hours) external onlyOwner {
        require(_hours >= 48 && _hours <= 72, "Window must be 48-72 hours");
        aiReviewWindow = _hours * 1 hours;
        emit AIReviewWindowUpdated(aiReviewWindow);
    }

    // Launch campaign (any filmmaker — anti-gatekeeping)
    function launchCampaign(
        string calldata metadataHash,
        uint256 target,
        uint256[] calldata milestoneAmounts,
        uint256[3] calldata tierPrices,
        uint256[3] calldata tierMaxSupplies,
        uint256 deadline
    ) external returns (uint256 campaignId) {
        require(bytes(metadataHash).length > 0, "Metadata required");
        require(target > 0 && milestoneAmounts.length > 0, "Invalid campaign");
        require(deadline > block.timestamp, "Deadline in past");

        campaignId = nextCampaignId++;

        Campaign storage c = campaigns[campaignId];
        c.filmmaker = msg.sender;
        c.metadataHash = metadataHash;
        c.target = target;
        c.deadline = deadline;
        c.status = CampaignStatus.ACTIVE;

        for (uint8 i = 0; i < 3; i++) {
            c.tiers[i] = TierConfig({
                price: tierPrices[i],
                maxSupply: tierMaxSupplies[i],
                sold: 0
            });
        }

        for (uint256 i = 0; i < milestoneAmounts.length; i++) {
            c.milestones.push(Milestone({
                desc: "", // Descriptions in Arweave metadata
                amount: milestoneAmounts[i],
                approved: false,
                approvedAt: 0,
                isAI: false,
                proofHash: "",
                aiReviewDeadline: 0
            }));
        }

        emit CampaignLaunched(campaignId, msg.sender, metadataHash, target);
    }

    // Backer contributes and receives InvestmentNFT (acts as access + proof)
    function contribute(uint256 campaignId, MovieTicket.Tier tier) external payable nonReentrant returns (uint256 tokenId) {
        Campaign storage c = campaigns[campaignId];
        require(c.status == CampaignStatus.ACTIVE, "Not active");
        require(block.timestamp < c.deadline, "Deadline passed");
        require(uint8(tier) < 3, "Invalid tier");

        TierConfig storage tc = c.tiers[uint8(tier)];
        require(tc.sold < tc.maxSupply, "Tier sold out");
        require(msg.value >= tc.price, "Insufficient payment");

        uint256 localId = tc.sold; // simple per-tier local id for now
        tokenId = campaignId * 10000 + uint8(tier) * 1000 + localId; // campaign-scoped

        _safeMint(msg.sender, tokenId);
        tokenCampaign[tokenId] = campaignId;
        tokenTiers[tokenId] = tier;
        _mintedTokens.push(tokenId);

        tc.sold++;
        c.raised += msg.value;
        campaignEscrow[campaignId] += msg.value;
        backerTotals[campaignId][msg.sender] += msg.value;

        if (c.raised >= c.target) {
            c.status = CampaignStatus.FUNDED;
        }

        emit Contribution(campaignId, msg.sender, tier, msg.value, tokenId);
        return tokenId;
    }

    // Producer-tier backers only (check via owned InvestmentNFT + tier)
    function submitAIProof(uint256 campaignId, uint256 mId, string calldata proofHash) external {
        require(_ownsProducerInvestment(msg.sender, campaignId), "Must own Producer InvestmentNFT");
        Milestone storage m = campaigns[campaignId].milestones[mId];
        require(!m.approved && bytes(m.proofHash).length == 0, "Already submitted");

        m.isAI = true;
        m.proofHash = proofHash;
        m.aiReviewDeadline = block.timestamp + aiReviewWindow;

        emit MilestoneSubmitted(campaignId, mId, proofHash, true);
    }

    // Owner-only AI review (enforces 48-72h window)
    function reviewAISubmission(uint256 campaignId, uint256 mId, bool approved) external onlyOwner {
        Milestone storage m = campaigns[campaignId].milestones[mId];
        require(m.isAI, "Not an AI submission");
        require(block.timestamp <= m.aiReviewDeadline, "Review window closed");

        if (!approved) {
            m.proofHash = ""; // allow re-submit
            m.isAI = false;
            m.aiReviewDeadline = 0;
        }

        emit AIReviewed(campaignId, mId, approved);
    }

    // Owner approves and releases tranche from escrow
    function approveMilestoneAndRelease(uint256 campaignId, uint256 mId) external onlyOwner nonReentrant {
        Campaign storage c = campaigns[campaignId];
        Milestone storage m = c.milestones[mId];

        if (m.isAI) {
            require(block.timestamp > m.aiReviewDeadline || m.approved, "AI review pending");
        }
        require(!m.approved, "Already released");
        require(campaignEscrow[campaignId] >= m.amount, "Insufficient escrow");

        m.approved = true;
        m.approvedAt = block.timestamp;
        campaignEscrow[campaignId] -= m.amount;

        (bool sent, ) = c.filmmaker.call{value: m.amount}("");
        require(sent, "Transfer failed");

        // Check if all milestones approved
        bool allApproved = true;
        for (uint256 i = 0; i < c.milestones.length; i++) {
            if (!c.milestones[i].approved) allApproved = false;
        }
        if (allApproved) c.status = CampaignStatus.DELIVERED;

        emit MilestoneReleased(campaignId, mId, m.amount, c.filmmaker);
    }

    function claimRefund(uint256 campaignId) external nonReentrant {
        Campaign storage c = campaigns[campaignId];
        require(c.status == CampaignStatus.FAILED || (block.timestamp > c.deadline && c.raised < c.target), "Not refundable");

        uint256 amt = backerTotals[campaignId][msg.sender];
        require(amt > 0 && campaignEscrow[campaignId] >= amt, "No refund due");

        backerTotals[campaignId][msg.sender] = 0;
        campaignEscrow[campaignId] -= amt;

        (bool sent, ) = msg.sender.call{value: amt}("");
        require(sent);

        emit RefundClaimed(campaignId, msg.sender, amt);
    }

    // View: does user own a Producer-tier InvestmentNFT for this campaign?
    function _ownsProducerInvestment(address user, uint256 campaignId) internal view returns (bool) {
        // Improved Phase 0 enumeration over only actual minted tokens (fixes prior sparse-ID + missing _nextTokenId issues)
        for (uint256 i = 0; i < _mintedTokens.length; i++) {
            uint256 tid = _mintedTokens[i];
            if (tokenCampaign[tid] == campaignId && tokenTiers[tid] == MovieTicket.Tier.PRODUCER) {
                try this.ownerOf(tid) returns (address owner) {
                    if (owner == user) return true;
                } catch {}
            }
        }
        return false;
    }

    // Accurate totalSupply: count of minted InvestmentNFTs (used by frontend scans + views)
    function totalSupply() public view returns (uint256) {
        return _mintedTokens.length;
    }

    // Phase 0: associate a campaign with the videoHash it grants crowdfund backer access to.
    // Called by the filmmaker or platform owner (e.g. once film is delivered via final milestone).
    // Enables the clean hasCrowdfundAccess check below.
    function setCampaignVideo(uint256 campaignId, string memory videoHash) external {
        Campaign storage c = campaigns[campaignId];
        require(c.filmmaker != address(0), "Campaign does not exist");
        require(msg.sender == c.filmmaker || msg.sender == owner(), "Not authorized");
        require(bytes(videoHash).length > 0, "Video hash required");
        campaignVideoHash[campaignId] = videoHash;
        emit CampaignVideoLinked(campaignId, videoHash);
    }

    /**
     * @dev Clean public view for crowdfund backer video gating.
     * Returns true if `user` owns any InvestmentNFT (DFCP) for a campaign whose
     * campaignVideoHash matches the given `videoHash`.
     * (Phase 0 uses explicit on-chain mapping set via setCampaignVideo, since
     * full campaign metadata lives on Arweave and cannot be parsed in Solidity.)
     */
    function hasCrowdfundAccess(address user, string memory videoHash) public view returns (bool) {
        if (user == address(0) || bytes(videoHash).length == 0) return false;

        bytes32 target = keccak256(bytes(videoHash));
        for (uint256 i = 0; i < _mintedTokens.length; i++) {
            uint256 tid = _mintedTokens[i];
            try this.ownerOf(tid) returns (address owner) {
                if (owner == user) {
                    uint256 cid = tokenCampaign[tid];
                    string memory linked = campaignVideoHash[cid];
                    if (bytes(linked).length > 0 && keccak256(bytes(linked)) == target) {
                        return true;
                    }
                }
            } catch {}
        }
        return false;
    }

    // Admin emergency
    function emergencyRefundAll(uint256 campaignId) external onlyOwner {
        // Implementation left as exercise for full version (loop backers or use recorded totals)
    }

    // ERC721 overrides
    function tokenURI(uint256 tokenId) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC721URIStorage) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/MovieTicket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "erc721a/contracts/ERC721A.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title MovieTicket
 * @dev Decentralflix Movie Ticket NFT — Utility/Access Token Only
 *
 * IMPORTANT LEGAL POSTURE (per user-provided research + ToS integration — Step 3):
 * - This contract issues UTILITY-ONLY access tokens (Basic/Deluxe/Producer tiers).
 * - Grants on-chain verified access to films + review rights (see hasAccessToVideo).
 * - NO securities, NO investment contracts, NO expectation of profit or returns.
 * - Fully non-custodial: all value flows wallet-to-wallet via direct contract calls.
 * - Platform (operator) never takes custody of funds or NFTs.
 *
 * Section 230 (Communications Decency Act) + DMCA Safe Harbor:
 * The broader Decentralflix platform relies on Section 230 immunity for third-party UGC.
 * This contract only handles access gating and payments; it does not host or moderate content.
 * DMCA: Takedowns affect access links/metadata only (immutability of chain respected).
 *
 * Producer tier + FilmmakerCampaign crowdfunding carries elevated legal risk (Howey analysis).
 * See docs/legal/RESEARCH_AND_INTEGRATION.md and ToS §4 for mandatory disclaimers.
 *
 * All users must accept the clickwrap ToS/Privacy before any mint or crowdfund action.
 *
 * All legal documents and contract comments must be reviewed by licensed counsel before mainnet.
 * This contract is provided as part of the production build for demonstration purposes.
 *
 * Supports two types of tokens:
 *   1. Permanent Access Passes (soulbound-style or transferable)
 *   2. Burnable Single-Watch Tickets
 *
 * Higher tiers can mint additional burnable tickets that reappear in the buyer's wallet.
 */
contract MovieTicket is ERC721A, Ownable, ReentrancyGuard {
    // Business counter for videoMetadata keys (kept in sync with ERC721A token IDs via spot minting).
    // We no longer shadow ERC721A's totalSupply() or _nextTokenId().
    uint256 private _videoCounter;
    bool private _paused;
    uint256 public platformFeeBps; // e.g. 3000 = 30%

    // URI storage (ERC721A does not include ERC721URIStorage by default)
    mapping(uint256 => string) private _tokenURIs;

    enum TicketType {
        PERMANENT_PASS,
        BURNABLE_TICKET
    }

    enum Tier {
        BASIC,
        DELUXE,
        PRODUCER
    }

    struct VideoMetadata {
        string videoHash;      // Arweave or IPFS hash
        address creator;
        uint256 price;
        bool isActive;
    }

    mapping(uint256 => VideoMetadata) public videoMetadata;
    mapping(uint256 => TicketType) public ticketTypes;
    mapping(uint256 => Tier) public tokenTiers;   // New: supports Basic / Deluxe / Producer
    mapping(uint256 => bool) public hasBeenWatched;

    // Producer tier perks stub (can be expanded with voting, AI collab rights, etc.)
    mapping(uint256 => bool) public hasProducerRights;

    event VideoMinted(
        uint256 indexed tokenId,
        address indexed creator,
        address indexed to,
        string videoHash,
        TicketType ticketType,
        Tier tier,
        uint256 price,
        uint256 platformFee,
        uint256 creatorShare
    );
    event CreatorPaid(uint256 indexed tokenId, address indexed creator, uint256 amount);
    event TicketBurned(uint256 indexed tokenId, address indexed viewer);
    event Paused(address account);
    event Unpaused(address account);
    event PlatformFeeUpdated(uint256 oldFeeBps, uint256 newFeeBps);
    event TierUpgraded(uint256 indexed tokenId, Tier newTier); // Future: allow upgrading tiers

    constructor(uint256 _initialPlatformFeeBps) ERC721A("Decentralflix Movie Ticket", "DFMT") Ownable(msg.sender) {
        require(_initialPlatformFeeBps <= 5000, "Fee too high (max 50%)");
        platformFeeBps = _initialPlatformFeeBps;
    }

    /**
     * @dev ERC721A hook — start token IDs at 0 to match prior ERC721 behavior.
     */
    function _startTokenId() internal pure override returns (uint256) {
        return 0;
    }

    /**
     * @dev Internal helper to set token URI (replaces ERC721URIStorage behavior).
     */
    function _setTokenURI(uint256 tokenId, string memory uri) internal {
        _tokenURIs[tokenId] = uri;
    }

    modifier whenNotPaused() {
        require(!_paused, "MovieTicket: paused");
        _;
    }

    function pause() public onlyOwner {
        _paused = true;
        emit Paused(msg.sender);
    }

    function unpause() public onlyOwner {
        _paused = false;
        emit Unpaused(msg.sender);
    }

    function setPlatformFee(uint256 newFeeBps) public onlyOwner {
        require(newFeeBps <= 5000, "Fee too high (max 50%)");
        uint256 oldFee = platformFeeBps;
        platformFeeBps = newFeeBps;
        emit PlatformFeeUpdated(oldFee, newFeeBps);
    }

    function withdraw() public onlyOwner nonReentrant {
        (bool success, ) = owner().call{value: address(this).balance}("");
        require(success, "Withdraw failed");
    }

    function mintPermanentPass(
        address to,
        address creator,
        string memory videoHash,
        uint256 price,
        Tier tier // New parameter for multi-tier support
    ) public payable onlyOwner whenNotPaused nonReentrant returns (uint256) {
        require(msg.value >= price, "Insufficient payment");
        require(uint8(tier) <= uint8(Tier.PRODUCER), "Invalid tier");

        uint256 platformFee = (price * platformFeeBps) / 10000;
        uint256 creatorShare = price - platformFee;

        uint256 tokenId = _videoCounter++;

        // Pay creator immediately (protects them from future gas price increases)
        if (creatorShare > 0) {
            (bool sent, ) = creator.call{value: creatorShare}("");
            require(sent, "Creator payment failed");
            emit CreatorPaid(tokenId, creator, creatorShare);
        }

        _safeMintSpot(to, tokenId); // ERC721A spot mint for exact ID control (keeps our totalSupply IDs)
        _setTokenURI(tokenId, videoHash);

        videoMetadata[tokenId] = VideoMetadata({
            videoHash: videoHash,
            creator: creator,
            price: price,
            isActive: true
        });

        ticketTypes[tokenId] = TicketType.PERMANENT_PASS;
        tokenTiers[tokenId] = tier;

        if (tier == Tier.PRODUCER) {
            hasProducerRights[tokenId] = true;
        }

        emit VideoMinted(
            tokenId,
            creator,
            to,
            videoHash,
            TicketType.PERMANENT_PASS,
            tier,
            price,
            platformFee,
            creatorShare
        );
        return tokenId;
    }

    function mintBurnableTicket(
        address to,
        address creator,
        string memory videoHash,
        uint256 price,
        Tier tier // New parameter for multi-tier support
    ) public payable onlyOwner whenNotPaused nonReentrant returns (uint256) {
        require(msg.value >= price, "Insufficient payment");
        require(uint8(tier) <= uint8(Tier.PRODUCER), "Invalid tier");

        uint256 platformFee = (price * platformFeeBps) / 10000;
        uint256 creatorShare = price - platformFee;

        uint256 tokenId = _videoCounter++;

        // Pay creator immediately (protects them from future gas price increases)
        if (creatorShare > 0) {
            (bool sent, ) = creator.call{value: creatorShare}("");
            require(sent, "Creator payment failed");
            emit CreatorPaid(tokenId, creator, creatorShare);
        }

        _safeMintSpot(to, tokenId); // ERC721A spot mint for exact ID control (keeps our totalSupply IDs)
        _setTokenURI(tokenId, videoHash);

        videoMetadata[tokenId] = VideoMetadata({
            videoHash: videoHash,
            creator: creator,
            price: price,
            isActive: true
        });

        ticketTypes[tokenId] = TicketType.BURNABLE_TICKET;
        tokenTiers[tokenId] = tier;

        if (tier == Tier.PRODUCER) {
            hasProducerRights[tokenId] = true;
        }

        emit VideoMinted(
            tokenId,
            creator,
            to,
            videoHash,
            TicketType.BURNABLE_TICKET,
            tier,
            price,
            platformFee,
            creatorShare
        );
        return tokenId;
    }

    // Burn a single-watch ticket after viewing (or on first play)
    function burnTicket(uint256 tokenId) public {
        require(ownerOf(tokenId) == msg.sender, "Not ticket owner");
        require(ticketTypes[tokenId] == TicketType.BURNABLE_TICKET, "Not a burnable ticket");
        require(!hasBeenWatched[tokenId], "Ticket already used");

        hasBeenWatched[tokenId] = true;
        _burn(tokenId);

        emit TicketBurned(tokenId, msg.sender);
    }

    // View function to check if a wallet has access to a specific video
    // TODO: Implement proper access check via events or subgraph in Phase 1+
    function hasAccess(address /*viewer*/, string memory /*videoHash*/) public pure returns (bool) {
        return true; // Placeholder for MVP
    }

    // === Fee Calculation Helpers (for frontend / off-chain use) ===

    function getPlatformFee(uint256 price) public view returns (uint256) {
        return (price * platformFeeBps) / 10000;
    }

    function getCreatorShare(uint256 price) public view returns (uint256) {
        return price - getPlatformFee(price);
    }

    function getCurrentPlatformFeeBps() public view returns (uint256) {
        return platformFeeBps;
    }

    // Legacy linear scan helper (Phase 0 / low volume only)
    // 
    // WARNING: This function iterates over totalSupply and does NOT scale.
    // Per ADR-001 (Mass-Scale Architecture), production systems MUST use an indexer
    // (The Graph or custom) that materializes ownership from VideoMinted + transfer events.
    //
    // This function is kept for backward compatibility and demo purposes only.
    // New code should prefer event-driven queries or a reverse mapping (to be added in v2).
    function hasAccessToVideo(address user, string memory videoHash) public view returns (bool) {
        for (uint256 i = 0; i < _videoCounter; i++) {
            if (videoMetadata[i].creator != address(0) && 
                keccak256(bytes(videoMetadata[i].videoHash)) == keccak256(bytes(videoHash)) &&
                ownerOf(i) == user) {
                return true;
            }
        }
        return false;
    }

    // The following functions are overrides required by Solidity.
    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721A)
        returns (string memory)
    {
        string memory uri = _tokenURIs[tokenId];
        if (bytes(uri).length == 0) {
            return super.tokenURI(tokenId); // fallback to ERC721A default (empty or base)
        }
        return uri;
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721A)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/Reviews.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./MovieTicket.sol";
import "./FilmmakerCampaign.sol";

/**
 * @title Reviews
 * @dev Decentralized, NFT-gated ratings and comments system — CORE PRODUCT FEATURE.
 *
 * Only verified owners (MovieTicket OR FilmmakerCampaign InvestmentNFT via hasCrowdfundAccess)
 * can submit/edit a single review per film. This enforces "your voice is verified because you own it on-chain".
 *
 * LEGAL TIE-IN (Step 3):
 * - Gating relies on the utility NFTs defined in MovieTicket + FilmmakerCampaign.
 * - Section 230 protects the platform for hosting these third-party reviews.
 * - DMCA: Reviews containing infringing material can be delisted via platform action (no on-chain deletion).
 * - All review eligibility is strictly on-chain (no off-chain KYC or custody).
 *
 * See ToS §3 (UGC + Zero-Censorship) and RESEARCH_AND_INTEGRATION.md.
 * All legal text and contract comments require review by licensed counsel before mainnet deployment.
 *
 * Only verified owners can review: holders of a MovieTicket OR crowdfund InvestmentNFT
 * (via FilmmakerCampaign.hasCrowdfundAccess after filmmaker calls setCampaignVideo).
 * This is the core social layer for the platform — verified owner voice only.
 */
contract Reviews {
    struct Review {
        address reviewer;
        uint8 rating;      // 1-5
        string comment;
        uint256 timestamp;
    }

    // videoHash => reviewer => Review  (enforces one review per user per film)
    mapping(string => mapping(address => Review)) private reviews;

    // videoHash => list of reviewers (for enumeration in Phase 0)
    mapping(string => address[]) public reviewersByVideo;

    MovieTicket public immutable movieTicket;
    FilmmakerCampaign public immutable filmmakerCampaign;

    event ReviewSubmitted(
        string indexed videoHash,
        address indexed reviewer,
        uint8 rating,
        string comment,
        uint256 timestamp
    );

    event ReviewUpdated(
        string indexed videoHash,
        address indexed reviewer,
        uint8 rating,
        string comment,
        uint256 timestamp
    );

    constructor(address _movieTicket, address _filmmakerCampaign) {
        movieTicket = MovieTicket(_movieTicket);
        filmmakerCampaign = FilmmakerCampaign(_filmmakerCampaign);
    }

    modifier onlyVerifiedOwner(string memory videoHash) {
        bool hasTicket = movieTicket.hasAccessToVideo(msg.sender, videoHash);
        bool hasCrowdfund = address(filmmakerCampaign) != address(0) &&
            filmmakerCampaign.hasCrowdfundAccess(msg.sender, videoHash);
        require(
            hasTicket || hasCrowdfund,
            "Must own a MovieTicket or crowdfund InvestmentNFT for this video to review"
        );
        _;
    }

    function submitReview(
        string memory videoHash,
        uint8 rating,
        string memory comment
    ) external onlyVerifiedOwner(videoHash) {
        require(rating >= 1 && rating <= 5, "Rating must be 1-5");
        require(bytes(comment).length > 0 && bytes(comment).length <= 500, "Comment too long");

        bool isNew = reviews[videoHash][msg.sender].reviewer == address(0);

        if (isNew) {
            reviewersByVideo[videoHash].push(msg.sender);
        }

        reviews[videoHash][msg.sender] = Review({
            reviewer: msg.sender,
            rating: rating,
            comment: comment,
            timestamp: block.timestamp
        });

        if (isNew) {
            emit ReviewSubmitted(videoHash, msg.sender, rating, comment, block.timestamp);
        } else {
            emit ReviewUpdated(videoHash, msg.sender, rating, comment, block.timestamp);
        }
    }

    function getReview(string memory videoHash, address reviewer) external view returns (Review memory) {
        return reviews[videoHash][reviewer];
    }

    function getReviews(string memory videoHash) external view returns (Review[] memory) {
        address[] memory reviewers = reviewersByVideo[videoHash];
        Review[] memory result = new Review[](reviewers.length);

        for (uint256 i = 0; i < reviewers.length; i++) {
            result[i] = reviews[videoHash][reviewers[i]];
        }
        return result;
    }

    function getReviewCount(string memory videoHash) external view returns (uint256) {
        return reviewersByVideo[videoHash].length;
    }

    function hasReviewed(string memory videoHash, address reviewer) external view returns (bool) {
        return reviews[videoHash][reviewer].reviewer != address(0);
    }
}

contracts/SeederCredits.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./MovieTicket.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SeederCredits
 * @dev Decentralflix P2P Hosting Credit System (Phase 0/1 hybrid MVP)
 *
 * Users earn redeemable credits by seeding/hosting film content.
 * Credits formula: uptime + bandwidth + peers (reported off-chain via Arweave, claimed on-chain).
 *
 * Hybrid design (per full vision):
 * - Heavy reports anchored on Arweave (immutable, censorship-resistant).
 * - On-chain lightweight ledger for balances + redemptions.
 * - Temporary platform attestor (owner-controlled EOA) for claim validation (bootstrap; replaceable later with multi-sig/indexers).
 *
 * Ties directly into NFT tiers: Higher tiers (Deluxe/Producer) get multipliers on earnings and redemptions.
 * Redeemable for perks (fee discounts, free tickets, future Producer eligibility).
 */
contract SeederCredits is Ownable, ReentrancyGuard {
    MovieTicket public immutable movieTicket;

    // Platform attestor (temporary trusted oracle for Phase 0/1; can be multi-sig later)
    address public platformAttestor;

    mapping(address => uint256) public credits;
    mapping(address => uint256) public lastClaimTimestamp;

    uint256 public constant MIN_CLAIM_COOLDOWN = 1 days;
    uint256 public constant MAX_REPORT_AGE = 7 days;

    // Events for transparency and indexing
    event CreditsEarned(
        address indexed seeder,
        uint256 amount,
        string arweaveTxId,
        uint256 tierMultiplier
    );
    event CreditsRedeemed(
        address indexed seeder,
        uint256 amount,
        bytes32 indexed rewardType
    );
    event PlatformAttestorUpdated(address oldAttestor, address newAttestor);

    constructor(address _movieTicket) Ownable(msg.sender) {
        require(_movieTicket != address(0), "Invalid MovieTicket");
        movieTicket = MovieTicket(_movieTicket);
        platformAttestor = msg.sender; // Owner starts as attestor
    }

    function setPlatformAttestor(address _newAttestor) external onlyOwner {
        require(_newAttestor != address(0), "Invalid attestor");
        address old = platformAttestor;
        platformAttestor = _newAttestor;
        emit PlatformAttestorUpdated(old, _newAttestor);
    }

    /**
     * @dev Claim credits from a signed Arweave report.
     * Report must be recent, signed by platformAttestor, and seeder must hold at least one ticket for referenced content.
     * Credits = (uptime + bandwidth + peers) * tierMultiplier (from highest owned tier).
     */
    function submitSeedingReport(
        string calldata arweaveTxId,
        uint256 claimedAmount,
        bytes calldata platformSignature
    ) external nonReentrant {
        require(bytes(arweaveTxId).length > 0, "Invalid Arweave TX");
        require(claimedAmount > 0, "Amount must be > 0");
        require(
            block.timestamp >= lastClaimTimestamp[msg.sender] + MIN_CLAIM_COOLDOWN,
            "Claim cooldown active"
        );

        // Verify platform signature (simple ECDSA for Phase 0/1)
        bytes32 messageHash = keccak256(
            abi.encodePacked(msg.sender, arweaveTxId, claimedAmount, block.chainid)
        );
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );

        address signer = recoverSigner(ethSignedMessageHash, platformSignature);
        require(signer == platformAttestor, "Invalid platform signature");

        // Apply tier multiplier (reuses existing MovieTicket tier logic)
        uint256 multiplier = getTierMultiplier(msg.sender); // 100 = 1.0x, 125 = 1.25x, 150 = 1.5x
        uint256 finalAmount = (claimedAmount * multiplier) / 100;

        credits[msg.sender] += finalAmount;
        lastClaimTimestamp[msg.sender] = block.timestamp;

        emit CreditsEarned(msg.sender, finalAmount, arweaveTxId, multiplier);
    }

    /**
     * @dev Redeem credits for perks (e.g. fee discount voucher, free ticket, Producer marker).
     * rewardType examples: "MINT_DISCOUNT_10", "FREE_BURNABLE_TICKET", "PRODUCER_ELIGIBLE"
     */
    function redeemCredits(uint256 amount, bytes32 rewardType) external nonReentrant {
        require(amount > 0 && credits[msg.sender] >= amount, "Insufficient credits");

        credits[msg.sender] -= amount;

        // Future: actually mint vouchers or interact with MovieTicket
        // For Phase 0/1 we just emit the event (frontend/off-chain applies the perk)
        emit CreditsRedeemed(msg.sender, amount, rewardType);
    }

    /**
     * @dev Returns tier multiplier for a user based on their highest owned MovieTicket tier.
     * Reuses the same scan pattern as hasAccessToVideo for consistency in Phase 0.
     */
    function getTierMultiplier(address user) public view returns (uint256) {
        // Simple scan (acceptable for Phase 0 while totalSupply small)
        uint256 supply = movieTicket.totalSupply();
        uint256 best = 100; // 1.0x default (BASIC)

        for (uint256 i = 0; i < supply; i++) {
            try movieTicket.ownerOf(i) returns (address owner) {
                if (owner == user) {
                    try movieTicket.tokenTiers(i) returns (MovieTicket.Tier t) {
                        if (t == MovieTicket.Tier.PRODUCER) return 150;
                        if (t == MovieTicket.Tier.DELUXE && best < 125) best = 125;
                    } catch {}
                }
            } catch {}
        }
        return best;
    }

    // Internal ECDSA recovery (standard)
    function recoverSigner(bytes32 hash, bytes memory signature) internal pure returns (address) {
        require(signature.length == 65, "Invalid signature length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(signature, 32))
            s := mload(add(signature, 64))
            v := byte(0, mload(add(signature, 96)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "Invalid v");
        return ecrecover(hash, v, r, s);
    }

    // Emergency / admin (owner only)
    function emergencySlash(address seeder, uint256 amount) external onlyOwner {
        if (credits[seeder] >= amount) {
            credits[seeder] -= amount;
        }
    }

    function pauseClaims() external onlyOwner {
        // Can be extended with pausable pattern if needed
    }
}

